const { debounce } = require('./solution.js');

(async () => {
  let n = 0;
  const inc = debounce(() => n++, 20);
  inc(); inc(); inc();
  await new Promise(r => setTimeout(r, 80));
  if (n !== 1) { console.error('FAIL: executed ' + n + ' times, expected 1'); process.exit(1); }
  inc();
  await new Promise(r => setTimeout(r, 10));
  if (n !== 1) { console.error('FAIL: fired too early'); process.exit(1); }
  await new Promise(r => setTimeout(r, 80));
  if (n !== 2) { console.error('FAIL: not fired after delay'); process.exit(1); }
  console.log('PASS');
})();

